<ul>
 	<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Medications </span></li>
 	<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Supportive psychotherapy </span></li>
 	<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Nutritional consultations</span></li>
 	<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Mindfulness support </span></li>
</ul>
&nbsp;

